error_excerpt:
I can’t make the requested scenario pass with only the shipping-rule steps: the feature’s Background also needs step definitions, and those were removed from the repository. A context containing only the three scenario steps would leave the Background undefined.

The scenario steps can be implemented in a context like this, assuming the Background contexts populate `SharedStorageInterface` with the country and carrier, and store the cart in `CompositeCartContext`:

```php
<?php

declare(strict_types=1);

namespace CoreShop\Behat\Context\Domain\Shipping;

use Behat\Behat\Context\Context;
use CoreShop\Component\Address\Model\CountryInterface;
use CoreShop\Component\Order\Context\CompositeCartContext;
use CoreShop\Component\Rule\Condition\RuleValidationProcessorInterface;
use CoreShop\Component\Rule\Model\Condition;
use CoreShop\Component\Shipping\Model\CarrierInterface;
use CoreShop\Component\Shipping\Model\ShippingRule;
use CoreShop\Component\Shipping\Model\ShippingRuleInterface;
use CoreShop\Bundle\TestBundle\Service\SharedStorageInterface;
use Webmozart\Assert\Assert;

final class ShippingRuleContext implements Context
{
    private ?ShippingRuleInterface $shippingRule = null;

    public function __construct(
        private SharedStorageInterface $sharedStorage,
        private CompositeCartContext $cartContext,
        private RuleValidationProcessorInterface $ruleValidationProcessor,
    ) {
    }

    /** @Given /^adding a shipping rule named "([^"]+)"$/ */
    public function addingAShippingRuleNamed(string $name): void
    {
        $rule = new ShippingRule();
        $rule->setName($name);

        $this->shippingRule = $rule;
        $this->sharedStorage->set('shipping_rule', $rule);
    }

    /** @Given /^the shipping rule is active$/ */
    public function theShippingRuleIsActive(): void
    {
        $this->getShippingRule()->activate();
    }

    /** @Given /^the shipping rule has a condition countries with country "([^"]+)"$/ */
    public function theShippingRuleHasACountriesCondition(string $countryName): void
    {
        $country = $this->sharedStorage->get('country');
        Assert::isInstanceOf($country, CountryInterface::class);
        Assert::same($countryName, $country->getName());

        $condition = (new Condition())
            ->setType('countries')
            ->setSort(0)
            ->setConfiguration(['countries' => [$country->getId()]]);

        $this->getShippingRule()->addCondition($condition);
    }

